import numpy as np

class Perceptron:
    def __init__(self, lr=0.1, n_epochs=50):
        self.lr = lr
        self.n_epochs = n_epochs

    def fit(self, X, y):
        n_samples, n_features = X.shape
        self.w = np.zeros(n_features)
        self.b = 0.0
        self.errores_por_epoca = []

        for epoca in range(self.n_epochs):
            errores = 0
            for xi, yi in zip(X, y):
                y_pred = np.sign(np.dot(self.w, xi) + self.b)
                y_pred = 1 if y_pred &gt;= 0 else -1
                if y_pred != yi:
                    self.w += self.lr * yi * xi
                    self.b += self.lr * yi
                    errores += 1
            self.errores_por_epoca.append(errores)
            if errores == 0:
                break
        return self

    def predict(self, X):
        z = X @ self.w + self.b
        return np.where(z &gt;= 0, 1, -1)
